// src/lib/scoring-platform/event-store.ts
function rowToEnvelope(row) {
  return {
    id: row.id,
    matchId: row.matchId,
    tournamentId: row.tournamentId,
    fixtureId: row.fixtureId,
    sportSlug: row.sportSlug,
    eventType: row.eventType,
    eventVersion: row.eventVersion,
    sequence: row.sequence,
    occurredAt: row.occurredAt,
    actorType: row.actorType,
    actorId: row.actorId,
    correlationId: row.correlationId,
    causationId: row.causationId,
    payload: row.payloadJson ?? {}
  };
}
async function loadMatchEvents(matchId, sportSlug, tx = db) {
  const conditions = [eq(scoringEventsTable.matchId, matchId)];
  if (sportSlug) {
    conditions.push(eq(scoringEventsTable.sportSlug, sportSlug));
  }
  const rows = await tx.select().from(scoringEventsTable).where(and(...conditions)).orderBy(asc(scoringEventsTable.sequence));
  return rows.map(rowToEnvelope);
}

